export const FORMAT = 'cyclescape-roads', VERSION = 4; // 4: three parts, every way, traffic inputs (3: one part; 2: the GSI graph)
export const GRID = 2 ** 26; // grid units across the world: z14 tiles of extent 4096
export const CUT_Z = 13;     // roads are cut at the borders of z13 tiles, so a leaf is never finer than that
export const gridX = (lon) => ((lon + 180) / 360) * GRID;
