// ---------------- rules that are part of the format ----------------
// Which links carry no elevation samples, and how many atoms a link has, are decided from the tags and the stored
// points by these rules, the same for writer and reader; changing one is a new format. (`traffic` is not: it is the
// app's rule for which links get a traffic estimate, graphFromLinks.)
const MOTOR_HW = new Set(['trunk', 'trunk_link', 'primary', 'primary_link', 'secondary', 'secondary_link', 'tertiary', 'tertiary_link',
  'unclassified', 'residential', 'road', 'living_street', 'service']);
