// The traffic estimate's measured inputs as stored, one byte each (0 = none): road density (km/km², 600 m window) as
// log10 in 0.01 steps, relief (m, ±500 m, at most 300) in 1.2 m steps, betweenness of the major network (log10(1 + bc)
// minus its median, traffic.mjs featureRow) in 1/32 steps from -3. encodeInputs takes the per-link means.
export const encodeInputs = (logD, relief, lbc) => [Math.max(1, Math.min(255, 1 + Math.round(Math.max(0, logD) * 100))),
  Math.max(1, Math.min(255, 1 + Math.round(Math.min(300, Math.max(0, relief)) / 1.2))), Number.isFinite(lbc) ? Math.max(1, Math.min(255, 1 + Math.round((lbc + 3) * 32))) : 0];
