// The live builder's grade caps (build-core.mjs MAX_GRADE, tunnels 3%, bridges 5%) as grade x 1e4
const CAP = { 1: 900, 2: 1000, 4: 1000, 6: 1200, 8: 1500, 9: 1500, 10: 1800, 11: 1000, 12: 2500, 13: 1500 };
export const gradeCap = (rc, flags) => (flags & 1 ? 300 : flags & 2 ? 500 : (CAP[rc] ?? 1500));
