// Motor-traffic estimate per road atom (vehicles/day, AADT-like), shared by the region tileset build
// (scripts/osm-region.mjs), the live builder (src/live/build-core.mjs) and the fits (scripts/fit-traffic-osm.mjs for
// the tileset's OpenStreetMap graph, scripts/fit-traffic.mjs for the archived prebuilt graphs).
//
// Model (research-traffic.md), coefficients per source in traffic-coeffs.mjs:
//   log10 V = b0 + b·[national, main pref, ordinary pref, width <5.5 m, >=13 m, >=19.5 m, 1-digit national]
//             + b_D·log10(road density km/km² in 600 m) + b_R·(relief within ±500 m / 100 m)
//             + b_B·(log10(1 + betweenness) - its median on major roads)          (Tier 2, when available)
//   The class and width terms are the graph's: on the OSM graph trunk / primary / secondary (classes 1, 2, 4), and the
//   width level from `width`, `lanes` and a divided carriageway (osm-tags.mjs). The source 'japanOsm' (the region
//   tileset) is fitted on the measured sections of the 2021 census in five Kanto cities, Miyagi and Iwate; 'osm' (live builds
//   from VersaTiles tiles, which carry no lanes or refs) and 'gsi' (GSI's road tiles) on Miyagi + Iwate.
//   Municipal roads (classes 6-9; the census counts few of them) are estimated as an ordinary prefectural road of
//   the same width, density and relief, then by their kind (osmRoad): tertiary has no cap, the formula times the
//   source's localScale (1.4 on both graphs); unclassified, residential, living_street and service at most 1,000;
//   under 3 m wide (rw 4: a driveway, an alley) 100 (research-traffic.md §4.3). Without a kind (osmRoad 0, a GSI
//   road with no OSM way along it) the width caps: under 5.5 m 1,000, 5.5-13 m 4,217.
// Betweenness: sampled, 20-minute radius, single shortest path by car travel time, on the MAJOR road network
// (national + prefectural roads). The tileset works it out on OSM's trunk, primary and secondary roads (with the
// roads only cars may use, one-way streets one way) within 10 km of a region (scripts/osm-region.mjs); the live
// builder from a ring of z11 major roads (src/live/major-ring.mjs). Municipal roads always use Tier 1. It is
// median-normalised so it does not depend on the sample count or graph size.
import { COEFFS } from './traffic-coeffs.mjs';

export const SPEED = { 1: 50, 2: 45, 4: 40, 6: 35, 8: 25, 9: 15 };      // km/h by class, motor traffic
export const TRUCK = { 1: 13, 2: 11, 4: 9, 6: 8, 8: 8, 9: 8 };          // large-vehicle share %, census class medians
// veh/day caps for municipal roads [assumption]. 4,217 = 10^(145/40), a value of the stored code grid (encodeV), so a
// capped road reads at least 4,000/day, the line where a road counts as busy
export const LOCAL_CAP = { narrow3: 100, w0: 1000, w1: 4217 };
// a municipal road of a major kind (OSM tertiary): the formula times this, no cap, where the source has no localScale
// of its own (traffic-coeffs.mjs)
export const LOCAL_MAJOR_SCALE = 1.4;
export const RADIUS_S = 20 * 60;
export const isMajorClass = (rc) => rc === 1 || rc === 2 || rc === 4;
const MAJOR = (rc) => rc === 1 || rc === 2 || rc === 4;

export const encodeV = (V) => (V > 0 ? Math.max(1, Math.min(255, Math.round(40 * Math.log10(V)) - 40)) : 0);
export const decodeV = (code) => (code ? 10 ** ((code + 40) / 40) : 0);

// local metric projection around the graph (equirectangular; fine for tens of km)
function projector(g) {
  let lat0 = g.meta?.bbox ? (g.meta.bbox[1] + g.meta.bbox[3]) / 2 : null;
  if (lat0 == null) { let s = 0; for (let i = 0; i < g.nNodes; i++) s += g.nodeLat[i]; lat0 = s / Math.max(1, g.nNodes); }
  const MX = 111320 * Math.cos((lat0 * Math.PI) / 180), MY = 110540;
  return { MX, MY };
}

// midpoint of every atom (local metres), by placing atoms along their chain polyline in proportion to length
export function atomMidpoints(g) {
  const { MX, MY } = projector(g);
  const mx = new Float64Array(g.nAtoms), my = new Float64Array(g.nAtoms);
  for (let c = 0; c < g.nChains; c++) {
    const c0 = g.coordStart[c], c1 = g.coordStart[c + 1];
    const xs = [], ys = [], cum = [0];
    for (let i = c0; i < c1; i++) { xs.push(g.coordLon[i] * MX); ys.push(g.coordLat[i] * MY); }
    for (let i = 1; i < xs.length; i++) cum.push(cum[i - 1] + Math.hypot(xs[i] - xs[i - 1], ys[i] - ys[i - 1]));
    const Lg = cum[cum.length - 1];
    let La = 0; for (let i = g.atomStart[c]; i < g.atomStart[c + 1]; i++) La += g.atomLen[i];
    const sc = La > 0 ? Lg / La : 0;
    let d = 0, q = 1;
    for (let i = g.atomStart[c]; i < g.atomStart[c + 1]; i++) {
      const s = (d + g.atomLen[i] / 2) * sc;
      while (q < cum.length - 1 && cum[q] < s) q++;
      const f = cum[q] > cum[q - 1] ? (s - cum[q - 1]) / (cum[q] - cum[q - 1]) : 0;
      mx[i] = xs.length > 1 ? xs[q - 1] + f * (xs[q] - xs[q - 1]) : xs[0];
      my[i] = xs.length > 1 ? ys[q - 1] + f * (ys[q] - ys[q - 1]) : ys[0];
      d += g.atomLen[i];
    }
  }
  return { mx, my };
}

// road density (km of road per km², all atoms of this graph) in a 600 m x 600 m window around each atom
export function density(g, mid) {
  const C = 100, grid = new Map();
  for (let i = 0; i < g.nAtoms; i++) { const k = Math.floor(mid.mx[i] / C) * 1e6 + Math.floor(mid.my[i] / C); grid.set(k, (grid.get(k) ?? 0) + g.atomLen[i]); }
  const out = new Float32Array(g.nAtoms);
  for (let i = 0; i < g.nAtoms; i++) {
    const gx = Math.floor(mid.mx[i] / C), gy = Math.floor(mid.my[i] / C); let s = 0;
    for (let a = -3; a < 3; a++) for (let b = -3; b < 3; b++) s += grid.get((gx + a) * 1e6 + gy + b) ?? 0;
    out[i] = s / 1000 / 0.36;
  }
  return out;
}

// relief: max - min road elevation within ±500 m (100 m cells), capped at 300 m
export function relief(g, mid) {
  const out = new Float32Array(g.nAtoms);
  if (!g.atomZ0) return out;
  const C = 100, lo = new Map(), hi = new Map();
  for (let i = 0; i < g.nAtoms; i++) {
    const z = (g.atomZ0[i] + g.atomZ1[i]) / 2, k = Math.floor(mid.mx[i] / C) * 1e6 + Math.floor(mid.my[i] / C);
    if (!(lo.get(k) <= z)) lo.set(k, z); if (!(hi.get(k) >= z)) hi.set(k, z);
  }
  for (let i = 0; i < g.nAtoms; i++) {
    const gx = Math.floor(mid.mx[i] / C), gy = Math.floor(mid.my[i] / C); let mn = Infinity, mxz = -Infinity;
    for (let a = -5; a <= 5; a++) for (let b = -5; b <= 5; b++) {
      const k = (gx + a) * 1e6 + gy + b, l = lo.get(k); if (l === undefined) continue;
      if (l < mn) mn = l; const h = hi.get(k); if (h > mxz) mxz = h;
    }
    out[i] = Number.isFinite(mn) ? Math.min(300, mxz - mn) : 0;
  }
  return out;
}

// dominant class / width level per chain, and whether it is part of the major network
function chainClass(g) {
  const rc = new Uint8Array(g.nChains), wc = new Uint8Array(g.nChains), tt = new Float64Array(g.nChains);
  for (let c = 0; c < g.nChains; c++) {
    const cnt = new Map(); let t = 0, wmax = 0;
    for (let i = g.atomStart[c]; i < g.atomStart[c + 1]; i++) {
      const r = g.atomRc[i], v = SPEED[r];
      t += v ? (g.atomLen[i] / 1000 / v) * 3600 : Infinity;
      cnt.set(r, (cnt.get(r) ?? 0) + g.atomLen[i]);
      if (g.atomAttr) wmax = Math.max(wmax, g.atomAttr[i] & 3);
    }
    rc[c] = [...cnt].sort((a, b) => b[1] - a[1])[0]?.[0] ?? 0; wc[c] = wmax; tt[c] = t;
  }
  return { rc, wc, tt };
}

// Sampled single-path betweenness on chains (travel-time weights), k random sources, bounded radius.
// keep(c) selects the chains of the network to use; returns Float64Array(nChains) (0 for chains not in it).
export function betweenness(g, keep, { k = 1500, radiusS = RADIUS_S, seed = 12345, tt } = {}) {
  const nC = g.nChains, nN = g.nNodes;
  const use = new Uint8Array(nC);
  for (let c = 0; c < nC; c++) use[c] = keep(c) && Number.isFinite(tt[c]) && g.chainA[c] !== g.chainB[c] ? 1 : 0;
  const deg = new Int32Array(nN + 1);
  for (let c = 0; c < nC; c++) if (use[c]) { deg[g.chainA[c] + 1]++; deg[g.chainB[c] + 1]++; }
  for (let i = 0; i < nN; i++) deg[i + 1] += deg[i];
  const adj = new Int32Array(deg[nN]), fill = deg.slice(0, nN);
  for (let c = 0; c < nC; c++) if (use[c]) { adj[fill[g.chainA[c]]++] = c; adj[fill[g.chainB[c]]++] = c; }
  const nodes = []; for (let i = 0; i < nN; i++) if (deg[i + 1] > deg[i]) nodes.push(i);
  const bc = new Float64Array(nC);
  if (!nodes.length) return bc;
  const dist = new Float64Array(nN).fill(Infinity), pred = new Int32Array(nN).fill(-1), sub = new Float64Array(nN);
  const order = new Int32Array(nN), heapN = new Int32Array(deg[nN] + 4), heapD = new Float64Array(deg[nN] + 4);
  let rng = seed >>> 0; const rand = () => ((rng = (Math.imul(rng, 1103515245) + 12345) >>> 0) / 4294967296);
  const K = Math.min(k, nodes.length);
  for (let s0 = 0; s0 < K; s0++) {
    const s = nodes[K === nodes.length ? s0 : Math.floor(rand() * nodes.length)];
    let hn = 0, no = 0;
    const push = (n, d) => { let i = hn++; while (i > 0) { const p = (i - 1) >> 1; if (heapD[p] <= d) break; heapN[i] = heapN[p]; heapD[i] = heapD[p]; i = p; } heapN[i] = n; heapD[i] = d; };
    dist[s] = 0; push(s, 0);
    while (hn) {
      const u = heapN[0], d = heapD[0], ln = heapN[--hn], ld = heapD[hn]; let i = 0;
      for (;;) { let c = 2 * i + 1; if (c >= hn) break; if (c + 1 < hn && heapD[c + 1] < heapD[c]) c++; if (heapD[c] >= ld) break; heapN[i] = heapN[c]; heapD[i] = heapD[c]; i = c; }
      heapN[i] = ln; heapD[i] = ld;
      if (d > dist[u]) continue;
      if (d > radiusS) break;
      order[no++] = u;
      for (let j = deg[u]; j < deg[u + 1]; j++) {
        const c = adj[j], v = g.chainA[c] === u ? g.chainB[c] : g.chainA[c], nd = d + tt[c];
        if (nd < dist[v]) { dist[v] = nd; pred[v] = c; push(v, nd); }
      }
    }
    for (let i = 0; i < no; i++) sub[order[i]] = 1;
    for (let i = no - 1; i > 0; i--) { const v = order[i], c = pred[v]; if (c < 0) continue; bc[c] += sub[v]; const u = g.chainA[c] === v ? g.chainB[c] : g.chainA[c]; sub[u] += sub[v]; }
    for (let i = 0; i < no; i++) { const v = order[i]; dist[v] = Infinity; pred[v] = -1; sub[v] = 0; }
    for (let i = 0; i < hn; i++) { dist[heapN[i]] = Infinity; pred[heapN[i]] = -1; }
  }
  return bc;
}

// log10(1+bc) minus its length-weighted median over major chains -> portable across sample sizes / graph extents
export function normaliseBc(g, bc, isMajor) {
  const vals = [];
  for (let c = 0; c < g.nChains; c++) if (isMajor(c) && bc[c] > 0) {
    let L = 0; for (let i = g.atomStart[c]; i < g.atomStart[c + 1]; i++) L += g.atomLen[i];
    vals.push([Math.log10(1 + bc[c]), L]);
  }
  vals.sort((a, b) => a[0] - b[0]);
  const tot = vals.reduce((s, v) => s + v[1], 0); let acc = 0, med = 0;
  for (const [v, L] of vals) { acc += L; if (acc >= tot / 2) { med = v; break; } }
  const out = new Float32Array(g.nChains).fill(NaN);
  for (let c = 0; c < g.nChains; c++) if (isMajor(c)) out[c] = Math.log10(1 + bc[c]) - med;
  return out;
}

// all per-atom features (the fit uses the same function)
// lbcChain: pre-normalised betweenness per chain (NaN = none), e.g. transferred from the live z11 ring network
// mid / D / R may be precomputed by the caller (the live builder computes density and relief from the full decoded
// network before level-of-detail culling, so outer through-roads keep unbiased predictors)
export function trafficFeatures(g, { lbcChain = null, betweennessK = 1500, mid = null, D = null, R = null } = {}) {
  mid ??= atomMidpoints(g); D ??= density(g, mid); R ??= relief(g, mid);
  const { rc: crc, tt } = chainClass(g);
  const isMajor = (c) => MAJOR(crc[c]);
  let lbc = lbcChain, bc = null;
  if (!lbc) { bc = betweenness(g, isMajor, { k: betweennessK, tt }); lbc = normaliseBc(g, bc, isMajor); }
  const atomChain = new Int32Array(g.nAtoms);
  for (let c = 0; c < g.nChains; c++) for (let i = g.atomStart[c]; i < g.atomStart[c + 1]; i++) atomChain[i] = c;
  return { mid, D, R, lbc, atomChain, bc };
}

// design row for one atom (the fit and the estimator share it)
export const FEATURES = ['national', 'mainpref', 'pref', 'w<5.5', 'w>=13', 'w>=19.5', '1-digit', 'log10 dens', 'relief/100m', 'bc'];
export function featureRow(g, i, F) {
  const rc = g.atomRc[i], a = g.atomAttr ? g.atomAttr[i] : 0, w = a & 3;
  const lbc = F.lbc[F.atomChain[i]];
  return [rc === 1 ? 1 : 0, rc === 2 ? 1 : 0, rc === 4 ? 1 : 0, w === 0 ? 1 : 0, w >= 2 ? 1 : 0, w === 3 ? 1 : 0, a & 4 ? 1 : 0,
    Math.log10(Math.max(1, F.D[i])), Math.min(300, F.R[i]) / 100, Number.isFinite(lbc) ? lbc : NaN];
}

// estimated vehicles/day for one atom; coefficients per source, Tier 2 (bc) when available else Tier 1.
// osmRoad: the kind of a municipal road (classes 6-9) by OSM: 1 a major one (tertiary), 2 a minor one (unclassified,
// residential, living_street, service), 0 unknown. Municipal roads always hit their width cap in towns, so the kind
// decides: a major road (3 m wide or more) has no cap and gets the formula x localScale (measured municipal arterials
// carry 9,000 to 15,000/day; the formula keeps a quiet rural tertiary quiet), a minor road at most 1,000 (Mitaka:
// 風の散歩道, one lane one way). rw 4 (under 3 m) is 100 whatever the kind.
export function estimateV(source, row, rc, rw, osmRoad = 0) {
  const C = COEFFS[source] ?? COEFFS.gsi;
  // the census has no municipal roads, so the class terms only identify national / main / ordinary prefectural;
  // municipal roads are estimated as an ordinary prefectural road of the same width, density and terrain,
  // then capped by width below
  if (rc >= 6 && rc <= 9) { row = row.slice(); row[0] = 0; row[1] = 0; row[2] = 1; }
  const useB = Number.isFinite(row[9]) && C.B;
  const beta = useB ? C.B : C.A;
  let y = beta[0];
  for (let j = 0; j < (useB ? 10 : 9); j++) y += beta[j + 1] * row[j];
  let V = 10 ** y;
  if (rc >= 6 && rc <= 9) { // municipal roads are outside the census: cap by width [assumption]
    const w = row[3] ? 0 : row[4] ? 2 : 1;
    // (not under 3 m: OSM's major road beside a GSI lane that OSM lacks would be taken for the lane's)
    if (osmRoad === 1 && rw !== 4) return V * (C.localScale ?? LOCAL_MAJOR_SCALE);
    let cap = rw === 4 ? LOCAL_CAP.narrow3 : w === 0 ? LOCAL_CAP.w0 : w === 1 ? LOCAL_CAP.w1 : Infinity;
    if (osmRoad === 2) cap = Math.min(cap, LOCAL_CAP.w0);
    V = Math.min(V, cap);
  }
  return V;
}

// fill g.atomTraffic / g.atomTruck (motor classes only; others 0). opts.osmRoad: per-atom estimateV osmRoad (or null)
export function computeTraffic(g, source, opts = {}) {
  const osmRoad = opts.osmRoad ?? null;
  const F = trafficFeatures(g, opts);
  g.atomTraffic = new Uint8Array(g.nAtoms); g.atomTruck = new Uint8Array(g.nAtoms);
  for (let i = 0; i < g.nAtoms; i++) {
    const rc = g.atomRc[i];
    if (!SPEED[rc]) continue;
    g.atomTraffic[i] = encodeV(estimateV(source, featureRow(g, i, F), rc, g.atomRw[i], osmRoad ? osmRoad[i] : 0));
    g.atomTruck[i] = TRUCK[rc] ?? 8;
  }
  return F;
}
