// Stairs on the road network (web/CONTRACT.md §2, atomFlags 16 and 32). GSI leaves its own steps (石段) out of the
// graph, but OSM maps many short flights where a GSI lane or path ends, a few metres long, which the "more than half
// of the link" vote of osm-class.mjs never sees. A steps way whose two ends both lie within END_M of one GSI chain
// is taken to be on it: the atoms between the two ends get flag 16 (steps), and also 32 when every flight on the
// atom has a wheeling ramp for bikes (ramp:bicycle). weights.mjs charges a fixed penalty for riding through.
// Pure: graph in, flags set; it runs in Node and in the browser's build worker (live builds and the tileset alike).
const KY = 110574, kxAt = (lat) => Math.cos((lat * Math.PI) / 180) * 111320;
export const STEPS = 16, STEPS_RAMP = 32;
export const END_M = 10;       // both ends of the flight within this of the chain
const MID_MAJOR_M = 4;         // on a wide municipal road (class 6) the flight's middle must lie within this
// On a road (classes 6, 8) a flight counts only at the road's end, where a street turns into stairs, and only a short
// one: along a road, or long and parallel to it, stairs are a pedestrian deck, a station or a footbridge beside it
// (three such flights of 22 to 39 m by the road south of Mitaka station)
const ROAD_FLIGHT_M = 15;
const CELL = 0.0005;           // grid of chain segments, degrees

// steps: [{ pts: [[lon, lat], ...], ramp: bool }]. Returns { ways, matched, skipped: { far, mainRoad, beside } }.
export function markSteps(graph, steps, { endM = END_M, matches = null } = {}) { // matches: an array to list each match in
  const st = { ways: steps.length, matched: 0, atoms: 0, byClass: {}, skipped: { far: 0, mainRoad: 0, beside: 0 } };
  if (!steps.length) return st;
  // chain segments near any flight only
  const want = new Set(), key = (x, y) => Math.floor(x / CELL) * 1e7 + Math.floor(y / CELL);
  for (const s of steps) for (const [x, y] of s.pts) for (let a = -1; a <= 1; a++) for (let b = -1; b <= 1; b++) want.add(key(x + a * CELL, y + b * CELL));
  const grid = new Map(), cls = new Uint8Array(graph.nChains);
  for (let c = 0; c < graph.nChains; c++) {
    const k0 = graph.coordStart[c], k1 = graph.coordStart[c + 1];
    for (let k = k0 + 1; k < k1; k++) {
      const x0 = graph.coordLon[k - 1], y0 = graph.coordLat[k - 1], x1 = graph.coordLon[k], y1 = graph.coordLat[k];
      for (let gx = Math.floor(Math.min(x0, x1) / CELL); gx <= Math.floor(Math.max(x0, x1) / CELL); gx++)
        for (let gy = Math.floor(Math.min(y0, y1) / CELL); gy <= Math.floor(Math.max(y0, y1) / CELL); gy++) {
          const kk = gx * 1e7 + gy; if (!want.has(kk)) continue; let l = grid.get(kk); if (!l) grid.set(kk, (l = [])); l.push(k);
        }
    }
    let best = 255, bl = -1; const by = new Map();
    for (let i = graph.atomStart[c]; i < graph.atomStart[c + 1]; i++) by.set(graph.atomRc[i], (by.get(graph.atomRc[i]) ?? 0) + graph.atomLen[i]);
    for (const [rc, L] of by) if (L > bl) { bl = L; best = rc; }
    cls[c] = best;
  }
  const chainOf = new Int32Array(graph.coordLon.length);
  for (let c = 0; c < graph.nChains; c++) for (let k = graph.coordStart[c]; k < graph.coordStart[c + 1]; k++) chainOf[k] = c;
  // distance from p to chain c's polyline near it, the metres along the chain there, and the unit direction of the
  // chain's segment there
  const near = (p, c) => {
    const kx = kxAt(p[1]); let bd = Infinity, at = 0, ux = 0, uy = 0;
    const k0 = graph.coordStart[c], k1 = graph.coordStart[c + 1]; let along = 0;
    for (let k = k0 + 1; k < k1; k++) {
      const ax = (graph.coordLon[k - 1] - p[0]) * kx, ay = (graph.coordLat[k - 1] - p[1]) * KY, dx = (graph.coordLon[k] - graph.coordLon[k - 1]) * kx, dy = (graph.coordLat[k] - graph.coordLat[k - 1]) * KY, L2 = dx * dx + dy * dy, L = Math.sqrt(L2);
      const u = L2 ? Math.max(0, Math.min(1, -(ax * dx + ay * dy) / L2)) : 0, d = Math.hypot(ax + u * dx, ay + u * dy);
      if (d < bd) { bd = d; at = along + u * L; ux = L ? dx / L : 0; uy = L ? dy / L : 0; }
      along += L;
    }
    return { d: bd, at, len: along, ux, uy };
  };
  const flagged = new Map(); // atom -> all flights on it have a ramp
  for (const s of steps) {
    const A = s.pts[0], B = s.pts[s.pts.length - 1], M = s.pts[Math.floor(s.pts.length / 2)];
    const mid = s.pts.length % 2 ? M : [(s.pts[s.pts.length / 2 - 1][0] + M[0]) / 2, (s.pts[s.pts.length / 2 - 1][1] + M[1]) / 2];
    const cand = new Set();
    for (const p of [A, B, mid]) for (let a = -1; a <= 1; a++) for (let b = -1; b <= 1; b++) for (const k of grid.get(key(p[0] + a * CELL, p[1] + b * CELL)) ?? []) cand.add(chainOf[k]);
    let pick = null, why = 'far';
    for (const c of cand) {
      const ea = near(A, c), eb = near(B, c); if (Math.max(ea.d, eb.d) > endM) continue;
      const em = near(mid, c), rc = cls[c];
      if (rc <= 4) { why = why === 'far' ? 'mainRoad' : why; continue; }        // national / prefectural roads have no stairs on them
      if (rc === 6 && em.d > MID_MAJOR_M) { why = 'beside'; continue; }         // a flight beside a wide road (a footbridge, a sidewalk)
      if (rc === 6 || rc === 8) {
        const ends = [graph.chainA[c], graph.chainB[c]].map((nd) => [graph.nodeLon[nd], graph.nodeLat[nd]]);
        const dEnd = Math.min(...[A, B].flatMap((p) => ends.map((q) => Math.hypot((p[0] - q[0]) * kxAt(p[1]), (p[1] - q[1]) * KY))));
        const flight = Math.hypot((B[0] - A[0]) * kxAt(A[1]), (B[1] - A[1]) * KY);
        if (dEnd > endM || flight > ROAD_FLIGHT_M) { why = 'beside'; continue; }
      }
      // closest to the flight's middle, ends at even distances, and running the same way (a flight at a junction is
      // on the chain it continues, not on one that turns off there): up to 8 m extra for a chain across the flight
      const kx = kxAt(mid[1]), fx = (B[0] - A[0]) * kx, fy = (B[1] - A[1]) * KY, fl = Math.hypot(fx, fy);
      const across = fl > 1 ? 1 - Math.abs((fx * em.ux + fy * em.uy) / fl) : 0;
      // a flight across the link (more than 60 degrees off it: steps up from a lane to a house or a shrine) or a long
      // one beside it (a path with a staircase next to it) is not on it
      if (fl > 2 && across > 0.5) { why = 'beside'; continue; }
      if (fl > ROAD_FLIGHT_M && em.d > MID_MAJOR_M) { why = 'beside'; continue; }
      const score = em.d + Math.abs(ea.d - eb.d) * 0.5 + 8 * across;
      if (!pick || score < pick.score) pick = { c, score, a0: Math.min(ea.at, eb.at), a1: Math.max(ea.at, eb.at), len: ea.len, mid: em.d, across };
    }
    if (!pick) { st.skipped[why]++; continue; }
    st.matched++; st.byClass[cls[pick.c]] = (st.byClass[cls[pick.c]] ?? 0) + 1;
    matches?.push({ id: s.id, rc: cls[pick.c], mid: pick.mid, across: pick.across, flight: Math.hypot((B[0] - A[0]) * kxAt(A[1]), (B[1] - A[1]) * KY), at: mid });
    // the atoms over [a0, a1] (atoms are spread along the line in proportion to their lengths); at least the one at the middle
    const c = pick.c, i0 = graph.atomStart[c], i1 = graph.atomStart[c + 1];
    let La = 0; for (let i = i0; i < i1; i++) La += graph.atomLen[i];
    const sc = pick.len > 0 ? La / pick.len : 0, lo = pick.a0 * sc, hi = pick.a1 * sc, m = (lo + hi) / 2;
    let acc = 0;
    for (let i = i0; i < i1; i++) {
      const s0 = acc, s1 = acc + graph.atomLen[i]; acc = s1;
      if (!((s1 >= lo && s0 <= hi) || (m >= s0 && m <= s1))) continue;
      flagged.set(i, (flagged.get(i) ?? true) && !!s.ramp);
    }
  }
  for (const [i, ramp] of flagged) graph.atomFlags[i] = (graph.atomFlags[i] & ~(STEPS | STEPS_RAMP)) | STEPS | (ramp ? STEPS_RAMP : 0);
  st.atoms = flagged.size;
  return st;
}
