// Level of detail for big live corridors.
//
// The memory a live build needs grows with the km of road it keeps. Small corridors keep everything. When the
// decoded network exceeds a road-km budget, the corridor gets two zones:
//   inner zone (within innerM of the route line): every road, as before
//   outer zone (innerM .. buffer): through-roads only -- national, prefectural and major local (class 1/2/4/6) --
//     or, if even that is too much, national + prefectural only (class 1/2/4)
// innerM is the largest distance that fits the budget (never below minInnerM). The traffic model's road-density
// and relief predictors are computed from the full decoded network before culling, so outer through-roads keep
// unbiased traffic estimates.
//
// Why z14 tiles everywhere (not lower-zoom tiles for the outer zone): GSI experimental_bvmap z13 does carry 96-99 %
// of major-road km with the same attributes (z12 only 26-58 %), but not the full minor network, which the density
// predictor needs. Culling while decoding gives the memory win; Cache Storage makes repeat runs fast.

export const LOD_DEFAULTS = {
  // road km kept per build. The compact builder needs ~10 MB per 1000 km (Mitaka->Fujiyoshida, 15 km buffer:
  // 41,600 km at 420 MB heap+arrays), so 60,000 km is ~0.6 GB. Culling changes routes (good quiet roads are often
  // minor roads well away from the straight line), so it is a last resort for very large corridors only.
  budgetKm: 60000,
  minInnerM: 3000,  // never cull minor roads closer than this to the route line
  binM: 100,        // resolution of the inner-zone search
};

// common road classes (scripts/build-resistance.mjs): 1 national, 2 main prefectural, 4 prefectural,
// 6 major local, 8 local, 9 narrow, 12 path, 13 garden/park road
// levels, gentlest first: 'local' drops narrow lanes (<3 m) and paths; 'major' keeps national/prefectural/major local;
// 'pref' keeps national/prefectural only
export const LEVELS = ['local', 'major', 'pref'];
export const isThroughRoad = (rc, level = 'major') => (level === 'pref' ? rc === 1 || rc === 2 || rc === 4
  : level === 'major' ? rc === 1 || rc === 2 || rc === 4 || rc === 6 : rc === 1 || rc === 2 || rc === 4 || rc === 6 || rc === 8);
const LEVEL_TEXT = { local: 'all roads except narrow lanes and paths', major: 'national/prefectural/major local roads', pref: 'national/prefectural roads' };

// links: { n, lenM: Float64Array, dmin: Float32Array, rc: Uint8Array, keep: Uint8Array (corridor/expressway filter) }
// returns { innerM, outer: 'all'|'major'|'pref', keptKm, totalKm, reason }
export function chooseLod(links, bufM, opts = {}) {
  const O = { ...LOD_DEFAULTS, ...opts };
  let totalKm = 0;
  for (let i = 0; i < links.n; i++) if (links.keep[i]) totalKm += links.lenM[i] / 1000;
  if (!(totalKm > O.budgetKm)) return { innerM: bufM, outer: 'all', keptKm: totalKm, totalKm, reason: 'full detail' };
  for (const level of LEVELS) {
    // km of through-roads (always kept) + histogram of other roads by distance to the route
    const nb = Math.ceil(bufM / O.binM) + 2, hist = new Float64Array(nb);
    let throughKm = 0;
    for (let i = 0; i < links.n; i++) {
      if (!links.keep[i]) continue;
      const km = links.lenM[i] / 1000;
      if (isThroughRoad(links.rc[i], level)) throughKm += km;
      else hist[Math.min(nb - 1, Math.max(0, Math.floor(links.dmin[i] / O.binM)))] += km;
    }
    let acc = throughKm, innerM = 0;
    for (let b = 0; b < nb; b++) {
      if (acc + hist[b] > O.budgetKm) break;
      acc += hist[b]; innerM = (b + 1) * O.binM;
    }
    if (innerM >= O.minInnerM) {
      innerM = Math.min(innerM, bufM);
      return { innerM, outer: level, keptKm: acc, totalKm, reason: `budget ${O.budgetKm} km: all roads within ${(innerM / 1000).toFixed(1)} km, ${LEVEL_TEXT[level]} beyond` };
    }
  }
  // even the minimum inner zone with only national/prefectural roads beyond is over budget: keep that, flag it
  let acc = 0;
  for (let i = 0; i < links.n; i++) if (links.keep[i] && (isThroughRoad(links.rc[i], 'pref') || links.dmin[i] <= O.minInnerM)) acc += links.lenM[i] / 1000;
  return { innerM: O.minInnerM, outer: 'pref', keptKm: acc, totalKm, overBudget: true,
    reason: `over budget (${Math.round(acc)} km > ${O.budgetKm} km) even with minimum detail: split the route into legs` };
}

// A rectangle (opts.area) has no route line, so its level of detail is uniform: the gentlest level whose roads fit
// the budget, over the whole box. innerM is 0; `outer` is the level everywhere.
export function chooseAreaLod(links, opts = {}) {
  const O = { ...LOD_DEFAULTS, ...opts };
  const kmOf = (level) => { let km = 0; for (let i = 0; i < links.n; i++) if (links.keep[i] && (!level || isThroughRoad(links.rc[i], level))) km += links.lenM[i] / 1000; return km; };
  const totalKm = kmOf(null);
  if (!(totalKm > O.budgetKm)) return { innerM: 0, outer: 'all', keptKm: totalKm, totalKm, reason: 'full detail' };
  for (const level of LEVELS) {
    const keptKm = kmOf(level);
    if (keptKm <= O.budgetKm) return { innerM: 0, outer: level, keptKm, totalKm, reason: `budget ${O.budgetKm} km: ${LEVEL_TEXT[level]} only` };
    if (level === 'pref') return { innerM: 0, outer: level, keptKm, totalKm, overBudget: true,
      reason: `over budget (${Math.round(keptKm)} km > ${O.budgetKm} km) even with minimum detail: choose a smaller area` };
  }
}

// keep a link under the chosen LOD?
export const keepLink = (lod, rc, dmin) => lod.outer === 'all' || dmin <= lod.innerM || isThroughRoad(rc, lod.outer);
