// Region packs: the road tileset (tileset.mjs, CONTRACT §7) as files per major region of Japan, which the app
// downloads whole and keeps in this browser, then reads leaf by leaf (format and rules: CONTRACT §7b).
// scripts/pack-tileset.mjs writes them; the app (app.mjs) decides which packs a route needs, asks, downloads them
// here; the build worker (live/build-worker.mjs) reads the roads out of them with readTileset.
//
// A pack is three files, its layers (tileset.mjs PARTS): base (the network and its tags, with the dictionary),
// elevation, and derived (runs and the traffic inputs). Each has its own SHA-256 in packs.json, and only a layer
// whose hash changed is downloaded again: a rebuild that changes values worked out at build time re-ships the
// derived layer, not the roads. A layer's header names the base it belongs to (its SHA-256), so layers of two
// builds never mix.
//
// Storage: IndexedDB database 'cyclescape-packs', store 'packs', one record per layer:
//   { id: '<pack>:<layer>', pack, layer, sha256, bytes, name, ja, built, stored, blob }
// (a record without `layer` is a pack of format 2, from before the layers: it is deleted). Each layer is kept as one
// Blob. Browsers keep a large Blob in IndexedDB as a file of its own and hand back a Blob backed by that file, so a
// leaf is read with blob.slice(offset, end).arrayBuffer(): only those bytes are read, and the pack is never in memory
// as a whole after it was stored.
import { leavesFor, decodeDict, unpackTile, PARTS } from './tileset.mjs';
export const LAYERS = PARTS; // ['base', 'elevation', 'derived']

export const PACK_FORMAT = 'cyclescape-pack', PACK_VERSION = 3; // 3: one file per layer (2: one file, a dictionary entry ahead of the leaves)
const MAGIC = [0x43, 0x53, 0x50, 0x4b], PAGE = 4096; // "CSPK"; the dictionary starts on a 4 KiB boundary

// File layout: "CSPK" | u8 version | 3 zero bytes | u32 LE H | H bytes of header JSON (padded with spaces) |
// the dictionary (gzip, tileset.mjs encodeDict; the base layer only, length 0 in the others) | the leaves (each its
// part of the tile, gzip). The header is `fields` plus { leaves: count, bytes: file size, dict: [offset, length],
// dir: [[z, x, y, offset, length], ...] }, offsets from the start of the file. `fields`: { format, version, id,
// layer, name, ja, bbox } and, for the base, osm (the extract's date: no build date, so a base whose roads did not
// change is the very same file), for the others base (the base layer's SHA-256). No build date in any of them: a
// layer whose contents did not change is the same file, and no browser downloads it again.
// entries: [[z, x, y, length], ...] in file order; dictLength: the dictionary's bytes. Returns the header bytes and the dir.
export function packHeader(fields, entries, dictLength = 0) {
  for (let start = PAGE; ; start += PAGE) {
    let off = start + dictLength;
    const list = entries.map(([z, x, y, len]) => { const e = [z, x, y, off, len]; off += len; return e; });
    const json = new TextEncoder().encode(JSON.stringify({ ...fields, leaves: list.length, bytes: off, dict: [start, dictLength], dir: list }));
    if (12 + json.length > start) continue;
    const head = new Uint8Array(start).fill(0x20);
    head.set(MAGIC, 0); head[4] = PACK_VERSION; head[5] = head[6] = head[7] = 0;
    new DataView(head.buffer).setUint32(8, start - 12, true);
    head.set(json, 12);
    return { head, dir: { list, bytes: off, dict: [start, dictLength] } };
  }
}
// The header of a pack from its first bytes (at least 12 + H): the parsed JSON, or an error for a file that is not one.
export function parsePackHeader(u8) {
  if (MAGIC.some((b, i) => u8[i] !== b)) throw new Error('not a road pack');
  if (u8[4] !== PACK_VERSION) throw new Error(`road pack version ${u8[4]}`);
  const H = new DataView(u8.buffer, u8.byteOffset).getUint32(8, true);
  if (u8.length < 12 + H) return { need: 12 + H };
  const h = JSON.parse(new TextDecoder().decode(u8.subarray(12, 12 + H)));
  if (h.format !== PACK_FORMAT) throw new Error(`unknown pack format ${h.format}`);
  return h;
}
// A Blob (or anything with slice()/arrayBuffer()) holding a pack -> fetchLeaf for readTileset over its leaves: each
// leaf comes with the pack's dictionary ({ bytes, dict }), read once
export async function packReader(blob) {
  let h = parsePackHeader(new Uint8Array(await blob.slice(0, PAGE).arrayBuffer()));
  if (h.need) h = parsePackHeader(new Uint8Array(await blob.slice(0, h.need).arrayBuffer()));
  if (blob.size !== h.bytes) throw new Error(`road pack ${h.id}: ${blob.size} bytes, header says ${h.bytes}`);
  const dir = new Map(h.dir.map(([z, x, y, off, len]) => [`${z}/${x}/${y}`, [off, len]]));
  let dictP = null;
  const dict = () => (dictP ??= h.dict[1] ? blob.slice(h.dict[0], h.dict[0] + h.dict[1]).arrayBuffer().then((b) => unpackTile(b)).then(decodeDict) : Promise.resolve(null));
  return { header: h, has: (t) => dir.has(`${t.z}/${t.x}/${t.y}`), dict,
    fetchLeaf: async (t) => {
      const e = dir.get(`${t.z}/${t.x}/${t.y}`); if (!e) throw new Error(`road tile ${t.z}/${t.x}/${t.y} is not in pack ${h.id}`);
      return { bytes: new Uint8Array(await blob.slice(e[0], e[0] + e[1]).arrayBuffer()), dict: await dict() };
    } };
}
// The three layers of a pack (records, or { blob, sha256 } each) -> one fetchLeaf for readTileset: { bytes (base),
// elevation, derived, dict }. Throws when a layer is of another pack or another base.
export async function layeredReader(recs) {
  const R = {}; for (const k of LAYERS) { if (!recs[k]) throw new Error(`road pack without its ${k} layer`); R[k] = await packReader(recs[k].blob); }
  const id = R.base.header.id;
  for (const k of LAYERS) {
    const h = R[k].header;
    if (h.id !== id || h.layer !== k) throw new Error(`road pack ${id}: the ${k} layer is ${h.id} ${h.layer}`);
    if (k !== 'base' && recs.base.sha256 && h.base !== recs.base.sha256) throw Object.assign(new Error(`road pack ${id}: the ${k} layer is of another build`), { name: 'PackMissing' });
  }
  return { header: R.base.header, has: R.base.has,
    fetchLeaf: async (t) => {
      const [b, e, d] = await Promise.all(LAYERS.map((k) => R[k].fetchLeaf(t)));
      return { bytes: b.bytes, elevation: e.bytes, derived: d.bytes, dict: b.dict };
    } };
}

// packs.json (doc): { format: 'cyclescape-packs', version: 3, tileset: index.json without its leaves,
//   packs: [{ id, name, ja, bytes, built, bbox, outline, leaves, layers: { base: { file, bytes, sha256 }, elevation:
//   {...}, derived: {...} } }], leaves: [[z, x, y, bytes, pack], ...] }   (bytes: the three layers together)
export const PACKS_VERSION = 3;
// what a pack is, as packs.json has it now: its layers' hashes; a stored pack is current when its key is the same
export const packKey = (p) => LAYERS.map((k) => p.layers?.[k]?.sha256 ?? '').join('.');
// the bytes still to download for pack p (a packs.json entry) given what is stored (a storedPacks entry or none)
export const missingBytes = (p, rec) => LAYERS.reduce((a, k) => a + (rec?.layers?.[k] === p.layers[k].sha256 ? 0 : p.layers[k].bytes), 0);
export const tilesetIndex = (doc) => ({ ...doc.tileset, leaves: doc.leaves });
// The packs a read needs ({ route, bufM } | { area }), as indexes into doc.packs; none: the place is outside them all.
const packOfLeaf = new WeakMap();
export function packsFor(doc, where) {
  let at = packOfLeaf.get(doc);
  if (!at) packOfLeaf.set(doc, (at = new Map(doc.leaves.map((l) => [`${l[0]}/${l[1]}/${l[2]}`, l[4]]))));
  return [...new Set(leavesFor(doc, where).map((t) => at.get(`${t.z}/${t.x}/${t.y}`)))].sort((a, b) => a - b);
}
export const packUrl = (base, p) => new URL(p.file, new URL(base.endsWith('/') ? base : `${base}/`, globalThis.location?.href)).href;
export async function loadPacksDoc(base, fetchFn = fetch) {
  const r = await fetchFn(packUrl(base, { file: 'packs.json' }), { cache: 'no-cache' });
  if (!r.ok) throw new Error(`packs.json: HTTP ${r.status}`);
  const doc = await r.json();
  if (doc.format !== 'cyclescape-packs' || doc.version !== PACKS_VERSION) throw new Error(`unknown packs.json format ${doc.format} ${doc.version}`);
  return doc;
}

// ---- this browser's packs (IndexedDB) ----
const DB = 'cyclescape-packs', STORE = 'packs';
let dbp = null;
const db = () => (dbp ??= new Promise((res, rej) => {
  const r = indexedDB.open(DB, 1);
  r.onupgradeneeded = () => r.result.createObjectStore(STORE, { keyPath: 'id' });
  r.onsuccess = () => { r.result.onversionchange = () => { r.result.close(); dbp = null; }; res(r.result); };
  r.onerror = () => { dbp = null; rej(r.error); };
}));
const tx = async (mode, fn) => { const d = await db(); return new Promise((res, rej) => { const t = d.transaction(STORE, mode), q = fn(t.objectStore(STORE)); t.oncomplete = () => res(q?.result); t.onerror = t.onabort = () => rej(t.error ?? new Error('aborted')); }); };
// every stored pack, without its blobs: [{ id, name, ja, built, stored, bytes, key, layers: { base: sha256, ... } }]
// (key as packKey: '' for a layer not stored). Records of format 2 are deleted on the way.
export async function storedPacks() {
  let all; try { all = await tx('readonly', (s) => s.getAll()); } catch { return []; }
  const old = all.filter((r) => !r.layer).map((r) => r.id);
  if (old.length) await tx('readwrite', (s) => { for (const id of old) s.delete(id); }).catch(() => {});
  const by = new Map();
  for (const { blob, ...r } of all) {
    if (!r.layer) continue;
    const m = by.get(r.pack) ?? by.set(r.pack, { id: r.pack, name: r.name, ja: r.ja, built: r.built, stored: r.stored, bytes: 0, layers: {} }).get(r.pack);
    m.layers[r.layer] = r.sha256; m.bytes += r.bytes; m.stored = Math.max(m.stored, r.stored);
    if (r.layer === 'base') Object.assign(m, { name: r.name, ja: r.ja });
  }
  for (const m of by.values()) m.key = LAYERS.map((k) => m.layers[k] ?? '').join('.');
  return [...by.values()];
}
// the stored layers of pack id: { base, elevation, derived } (records with their blobs; a missing one undefined)
export async function packLayers(id) {
  const recs = await Promise.all(LAYERS.map((k) => tx('readonly', (s) => s.get(`${id}:${k}`))));
  return Object.fromEntries(LAYERS.map((k, i) => [k, recs[i]]));
}
export const deletePack = (id) => tx('readwrite', (s) => { s.delete(id); for (const k of LAYERS) s.delete(`${id}:${k}`); });
export const clearPacks = () => tx('readwrite', (s) => s.clear());

// Download the layers of pack p (a packs.json entry) that are not stored as packs.json has them, check each one's
// size and SHA-256, and store it. onBytes(n): the bytes of this download so far (of missingBytes); signal: an
// AbortSignal (Cancel). A layer is stored only when the whole file arrived and checks out (one that did stays stored
// when a later one fails). Without WebCrypto (a page on plain http other than localhost) only the size is checked.
export async function downloadPack(base, p, { onBytes = () => {}, signal } = {}) {
  const have = (await storedPacks()).find((r) => r.id === p.id);
  let before = 0;
  for (const k of LAYERS) {
    const L = p.layers[k];
    if (have?.layers?.[k] === L.sha256) continue;
    const r = await fetch(packUrl(base, L), { signal, cache: 'no-store' }); // no-store: not a second copy in the HTTP cache
    if (!r.ok) throw Object.assign(new Error(`${L.file}: HTTP ${r.status}`), { unreachable: true });
    const buf = new Uint8Array(L.bytes), rd = r.body.getReader();
    let n = 0;
    for (;;) {
      const { done, value } = await rd.read(); if (done) break;
      if (n + value.length > buf.length) { rd.cancel(); throw new Error(`${L.file}: larger than packs.json says`); }
      buf.set(value, n); n += value.length; onBytes(before + n);
    }
    if (n !== L.bytes) throw new Error(`${L.file}: ${n} bytes, packs.json says ${L.bytes}`);
    if (globalThis.crypto?.subtle) {
      const h = [...new Uint8Array(await crypto.subtle.digest('SHA-256', buf))].map((b) => b.toString(16).padStart(2, '0')).join('');
      if (h !== L.sha256) throw new Error(`${L.file}: content does not match packs.json`);
    }
    await tx('readwrite', (s) => s.put({ id: `${p.id}:${k}`, pack: p.id, layer: k, sha256: L.sha256, bytes: L.bytes, name: p.name, ja: p.ja, built: p.built ?? null, stored: Date.now(), blob: new Blob([buf]) }));
    before += n;
  }
  try { await navigator.storage?.persist?.(); } catch { /* best effort: ask the browser not to evict it */ }
  return (await storedPacks()).find((r) => r.id === p.id);
}
