// Module Web Worker: builds the road graph for a route or a rectangle.
//   (message protocol below, at self.onmessage)
// The live sources build it from map tiles ('osmjp': Japan, OSM roads with GSI elevation; 'osm': anywhere; 'gsi': GSI's
// own road tiles, not used by the app), kept in Cache Storage for 30 days ('osm-tiles-v1', 'gsi-tiles-v1'): tile-cache.mjs. Source 'packs' reads it from the region packs stored in this
// browser (packs.mjs, CONTRACT §7b) with the tileset reader, and makes no request at all.
import { buildLiveGraph, graphBuffers } from './build-core.mjs';
import { TILE_CACHES, cachedTile } from './tile-cache.mjs';
import { LOD_DEFAULTS } from './lod.mjs';
import { readTileset } from '../tileset.mjs';
import { packsFor, packLayers, layeredReader, packKey, tilesetIndex, LAYERS } from '../packs.mjs';

const cachePromise = {};
const openCache = (source) => (cachePromise[source] ??= (self.caches ? caches.open(TILE_CACHES[source]).catch(() => null) : Promise.resolve(null)));
const fetchTile = async (source, url) => cachedTile(await openCache(source), url);

async function decodePng(bytes) {
  const bmp = await createImageBitmap(new Blob([bytes], { type: 'image/png' }), { premultiplyAlpha: 'none', colorSpaceConversion: 'none' });
  const cv = new OffscreenCanvas(bmp.width, bmp.height);
  const ctx = cv.getContext('2d', { willReadFrequently: true });
  ctx.drawImage(bmp, 0, 0);
  bmp.close();
  return ctx.getImageData(0, 0, cv.width, cv.height).data;
}

// The road graph from stored packs (doc: packs.json). A pack whose layers are not all stored as packs.json names
// them fails the build with err.name 'PackMissing'.
const readers = new Map(); // pack id -> { key, reader }: the parsed directories, kept between builds
async function readPacks(doc, where, opts) {
  const byPack = new Map();
  for (const k of packsFor(doc, where)) {
    const p = doc.packs[k];
    let r = readers.get(p.id);
    if (r?.key !== packKey(p)) {
      const recs = await packLayers(p.id).catch(() => ({}));
      if (LAYERS.some((k) => recs[k]?.sha256 !== p.layers[k].sha256)) throw Object.assign(new Error(`road pack ${p.id} is not stored`), { name: 'PackMissing' });
      r = { key: packKey(p), reader: await layeredReader(recs) };
      readers.set(p.id, r);
    }
    byPack.set(k, r.reader);
  }
  const at = new Map(doc.leaves.map((l) => [`${l[0]}/${l[1]}/${l[2]}`, l[4]]));
  return readTileset(tilesetIndex(doc), where, (t) => byPack.get(at.get(`${t.z}/${t.x}/${t.y}`)).fetchLeaf(t), opts);
}

// Protocol:
//   in:  { id, route, bufM, lod?, source?, area?, packs? }   build (lod: false = full detail, or { budgetKm, minInnerM }
//                                             overrides; source: 'osmjp' (default) | 'osm' | 'gsi' | 'packs'; area: [west,
//                                             south, east, north] builds that box, and route / bufM are then ignored;
//                                             packs: packs.json, for source 'packs')
//        { type: 'cancel', id }               stop build `id` at the next tile/stage boundary
//        { type: 'forget' }                   drop the parsed packs (after packs were deleted)
//   out: { id, type: 'progress', stage, done?, total? }   stages: fetch, decode, dem, grade, noding, typed, traffic;
//                                             packs: read (done / total leaves), typed
//        { id, type: 'done', graph, hazards, stats }      stats.lod = { innerM, outer, reason, keptKm, totalKm, culledKm, overBudget? }
//        { id, type: 'cancelled' } | { id, type: 'error', message, name }
const cancelled = new Set();
self.onmessage = async (ev) => {
  const msg = ev.data;
  if (msg?.type === 'cancel') { cancelled.add(msg.id); return; }
  if (msg?.type === 'forget') { readers.clear(); return; }
  const { id, route, bufM, lod, source = 'osmjp', area = null } = msg;
  const opts = { isCancelled: () => cancelled.has(id), ...(lod !== undefined ? { lod } : {}) };
  const progress = (p) => self.postMessage({ id, type: 'progress', ...p, ...(source === 'packs' && p.stage === 'fetch' ? { stage: 'read' } : {}) });
  try {
    const { graph, hazards, stats } = source === 'packs'
      ? await readPacks(msg.packs, area ? { area } : { route, bufM }, { lod: LOD_DEFAULTS, ...opts, onProgress: progress })
      : await buildLiveGraph(route, bufM, { fetchTile: (url) => fetchTile(source, url), decodePng }, { onProgress: progress, source, area, ...opts });
    self.postMessage({ id, type: 'done', graph, hazards, stats }, graphBuffers(graph));
  } catch (e) {
    if (e?.name === 'Cancelled') self.postMessage({ id, type: 'cancelled' });
    else self.postMessage({ id, type: 'error', message: e?.message ?? String(e), name: e?.name });
  } finally {
    cancelled.delete(id);
  }
};
