// OpenStreetMap tags -> the road graph's fields (web/CONTRACT.md §1, §2). The one place that decides what a way is:
// the tileset builder (scripts/fetch-osm-japan.mjs keeps or drops ways with keepWay, scripts/build-tileset.mjs
// classifies them for the traffic estimate) and the tileset reader (web/src/tileset.mjs, which rebuilds the graph
// from the tags every time it reads a pack) both call it, so a new rule here needs no rebuild of the packs.
//
// A way's tags are a plain object { key: value }. classify(tags) returns
//   rc      common road class (CONTRACT §1): 1 trunk, 2 primary, 4 secondary, 6 tertiary, 8 unclassified /
//           residential / road, 9 living_street / service / a paved track, 10 track, 11 cycleway (or a path
//           designated for bikes), 12 path / footway / steps, 13 a footway, pedestrian street or bridleway where
//           bikes are allowed
//   rw      width rank: 2 at least 5.5 m, 3 3 to 5.5 m, 4 under 3 m (from width, lanes, then the kind of road)
//   attr    bits 0-1 width level for the traffic model (0 under 5.5 m, 1 5.5-13 m, 2 13 m or 4 lanes and more,
//           3 19.5 m or 6 lanes, or a divided trunk / primary road); bit 2 a single-digit national route (ref 1-9)
//   flags   1 tunnel (classes 1-10), 2 bridge, 4 snow shed (avalanche protector or covered), 8 unpaved,
//           16 stairs, 32 with 16: stairs with a bike ramp, 32 alone: bicycle=dismount (walk the bike), 64 a sidewalk
//           not tagged for bikes, 128 a crossing with signals
//   bikeWay the way is a bike facility for the roads beside it (bike-infra.mjs): 2 dedicated, 3 shared, 0 none
//   roadBike a facility tagged on the road itself: 2 track, 1 painted lane, 0 none (classes 1-9 only)
//   foot    the way counts for footpath runs (class 12 and not a bike way)
//   motor   a road with motor traffic (classes 1-9): it gets a traffic estimate
//   local   for the traffic estimate's municipal rule (traffic.mjs estimateV osmRoad): 1 tertiary, 2 unclassified,
//           residential, road, living_street, service; 0 otherwise
import { bikeWayType, roadBikeTag } from './bike-infra.mjs';

export const UNPAVED = /^(unpaved|gravel|fine_gravel|compacted|dirt|earth|ground|grass|grass_paver|sand|mud|pebblestone|rock|stone|woodchips|soil|clay)$/;
const RC = { trunk: 1, trunk_link: 1, primary: 2, primary_link: 2, secondary: 4, secondary_link: 4, tertiary: 6, tertiary_link: 6,
  unclassified: 8, residential: 8, road: 8, living_street: 9, service: 9, track: 10, cycleway: 11,
  path: 12, footway: 12, pedestrian: 12, bridleway: 12, steps: 12 };
export const HIGHWAYS = new Set(Object.keys(RC)); // the highway values the graph has (motorways never)
const BIKE_OK = /^(yes|designated|permissive)$/;
const FOOT_HW = /^(footway|path|pedestrian|steps|bridleway)$/;
const NARROW_SERVICE = /^(driveway|alley|parking_aisle|drive-through|emergency_access)$/;
const yes = (v) => v != null && v !== '' && v !== 'no';

// Is this way in the graph at all? Bikes are banned on expressways whether or not tagged, so every motorway is out;
// so are motorroad=yes, bicycle=no, access=no|private unless bicycle allows it, and footways inside stations and
// buildings (indoor, platforms, escalators and moving walkways). Sidewalks and crossings stay:
// they are what joins station forecourts, pedestrian streets and park paths to the roads, and in Japan a bike may
// ride a sidewalk that is signed for it (most are not tagged so) or where the road is unsafe; classify() flags
// them (64 sidewalk, 128 signalled crossing) so the weights can cost them. Returns true, or why not.
export function keepWay(t) {
  const hw = t.highway;
  if (hw === 'motorway' || hw === 'motorway_link') return 'motorway';
  if (!HIGHWAYS.has(hw)) return 'highway';
  if (t.area === 'yes' && hw !== 'pedestrian' && hw !== 'footway') return 'area';
  if (t.motorroad === 'yes') return 'motorroad';
  if (t.bicycle === 'no') return 'bicycle';
  if ((t.access === 'no' || t.access === 'private') && !BIKE_OK.test(t.bicycle ?? '')) return 'access';
  // inside stations and buildings: concourses, platforms, lifts and escalators (no riding there; joined to the
  // streets by crossings they would start routes inside a station)
  if (FOOT_HW.test(hw) && ((t.indoor && t.indoor !== 'no') || t.conveying || t.railway === 'platform' || t.public_transport === 'platform')) return 'indoor';
  return true;
}
// Is this way in the road packs? More than the graph has, so a future rule can bring a way in without a rebuild
// (web/CONTRACT.md §7): every highway that exists except motorways and motorroad=yes (bikes are banned there by law),
// and ferries. keepWay above decides, when a pack is read, which of them the graph has. Returns true, or why not.
const GONE = /^(proposed|abandoned|razed|demolished|disused|dismantled|planned)$/;
export function storeWay(t) {
  const hw = t.highway;
  if (hw == null) return t.route === 'ferry' ? true : 'highway';
  if (hw === 'motorway' || hw === 'motorway_link') return 'motorway';
  if (t.motorroad === 'yes') return 'motorroad';
  if (GONE.test(hw)) return 'gone';
  return true;
}
export const isFerry = (t) => t.route === 'ferry' && t.highway == null;

// A road cars use that is not in the graph (a motorroad bypass, a trunk road closed to bikes): kept for the traffic
// estimate's betweenness only, which needs the network cars drive on
export const carOnly = (t) => keepWay(t) !== true && /^(trunk|primary|secondary)(_link)?$/.test(t.highway ?? '') && t.access !== 'no' && t.access !== 'private' && t.area !== 'yes';

const num = (v) => { const m = /^\s*([\d.]+)/.exec(String(v ?? '')); return m ? parseFloat(m[1]) : NaN; };

export function classify(t) {
  const hw = t.highway ?? '';
  let rc = RC[hw] ?? 12;
  const surface = t.surface, unpavedSurface = surface != null ? UNPAVED.test(surface) : null; // null: no surface tag
  if (rc === 10 && (t.tracktype === 'grade1' || unpavedSurface === false)) rc = 9; // a grade1 or paved track is a narrow lane
  if (hw === 'path' && t.bicycle === 'designated') rc = 11;
  else if (rc === 12 && (hw === 'footway' || hw === 'pedestrian' || hw === 'bridleway') && BIKE_OK.test(t.bicycle ?? '')) rc = 13;
  // width
  const width = num(t.width ?? t.est_width), lanes = Math.round(num(t.lanes));
  const major = rc <= 6, link = hw.endsWith('_link');
  let rw;
  if (width > 0) rw = width >= 5.5 ? 2 : width >= 3 ? 3 : 4;
  else if (lanes >= 2) rw = 2;
  else if (major && !(lanes === 1 && !link && t.oneway !== 'yes')) rw = 2;
  else if (hw === 'service') rw = NARROW_SERVICE.test(t.service ?? '') || !(lanes >= 1) ? 4 : 3;
  else rw = 3;
  let w = 0;
  if (rc <= 9) {
    const divided = (hw === 'trunk' || hw === 'primary') && (t.oneway === 'yes' || t.oneway === '-1') && lanes >= 2;
    const total = (t.oneway === 'yes' || t.oneway === '-1') && rc <= 4 && !link ? 2 * lanes : lanes;
    w = divided || width >= 19.5 || total >= 6 ? 3 : width >= 13 || total >= 4 ? 2 : width >= 5.5 || total >= 2 || (major && !(width > 0) && !(lanes >= 1)) ? 1 : 0;
  }
  const nat1 = rc === 1 && String(t.ref ?? '').split(/[;,]/).some((r) => /^\s*[1-9]\s*$/.test(r));
  // flags
  const tunnelTag = t.tunnel === 'yes' || t.tunnel === 'building_passage';
  let flags = 0;
  if (tunnelTag && rc <= 10) flags |= 1; // a cycleway or footpath underpass is a structure, not the hazard a road tunnel is
  if (yes(t.bridge) && !tunnelTag) flags |= 2;
  if (!tunnelTag && rc <= 10 && (t.tunnel === 'avalanche_protector' || t.covered === 'yes')) flags |= 4;
  if (unpavedSurface || (unpavedSurface === null && (hw === 'path' || (hw === 'track' && t.tracktype !== 'grade1')))) flags |= 8;
  if (hw === 'steps') { flags |= 16; if (t['ramp:bicycle'] === 'yes' || t['ramp:bicycle'] === 'designated') flags |= 32; }
  if (hw !== 'steps' && t.bicycle === 'dismount') flags |= 32; // walk the bike (32 without 16: not a stairs ramp)
  if (rc === 12 && t.footway === 'sidewalk') flags |= 64; // a sidewalk not tagged for bikes (one that is is class 13)
  if (t.footway === 'crossing' && (t.crossing === 'traffic_signals' || t['crossing:signals'] === 'yes')) flags |= 128;
  const bikeWay = bikeWayType(t);
  return { rc, rw, attr: w | (nat1 ? 4 : 0), flags, bikeWay, roadBike: rc <= 9 ? roadBikeTag(t) : 0,
    foot: rc === 12 && !bikeWay, motor: rc <= 9, local: rc === 6 ? 1 : rc === 8 || rc === 9 ? 2 : 0, structure: tunnelTag || yes(t.bridge) };
}

// classify() per entry of a list of tag objects (index 0 = none), worked out once per entry when first asked for
export function classifier(list) {
  const memo = new Array(list.length);
  return (id) => memo[id] ?? (memo[id] = classify(list[id] ?? {}));
}

// Tags dropped when the extract is parsed: where the data came from (source, source:*) and the editor's name. Every
// other tag is kept (notes, fixmes, survey and check dates, names in every language), so a future rule can read it.
export const noiseKey = (k) => k === 'source' || k.startsWith('source:') || k === 'created_by';
